joi_block.script:
if (not (all(#LeakSensor).leakSensor_leakage ==| true)) {
    wait until(all(#LeakSensor).leakSensor_leakage ==| true)
}
all(#Valve).valve_close()

if (not ((#BabyRoom_SoundSensor).soundSensor_sound > 40)) {
    wait until((#BabyRoom_SoundSensor).soundSensor_sound > 40)
}
(#LivingRoom_Speaker).speaker_speak("Noise detected in the baby room")

if (not ((#LaundryRoom_Fan).fan_speed <= 5)) {
    wait until((#LaundryRoom_Fan).fan_speed <= 5)
}
(#LivingRoom_Speaker).speaker_speak("The fan has slowed down")

if (not ((#LR_MB).multiButton_button2 == "pushed")) {
    wait until((#LR_MB).multiButton_button2 == "pushed")
}
all(#Light).light_moveToBrightness(100.0, 0.0)
delay(30 MIN)
all(#Light).light_moveToBrightness(30.0, 0.0)

if (not ((#Main_MB).multiButton_button3 == "pushed")) {
    wait until((#Main_MB).multiButton_button3 == "pushed")
}
delay(1 HOUR)
all(#Light).light_moveToBrightness(0.0, 0.0)

if (not ((#Bedroom_MB).multiButton_button1 == "pushed")) {
    wait until((#Bedroom_MB).multiButton_button1 == "pushed")
}
current = (#Bedroom_Light).light_currentBrightness
if (current >= 80) {
(#Bedroom_Light).light_moveToBrightness(10.0, 0.0)
}
else {
(#Bedroom_Light).light_moveToBrightness(80.0, 0.0)
}

triggered := false
if (triggered == true) {
if (not (not (all(#LightSensor).lightSensor_brightness <| 100))) {
    wait until(not (all(#LightSensor).lightSensor_brightness <| 100))
}
    triggered = false
}
wait until(all(#LightSensor).lightSensor_brightness <| 100)
all(#Light).light_moveToBrightness(100.0, 0.0)
triggered = true

triggered := false
if (triggered == true) {
if (not (not (all(#AirQualitySensor).airQualitySensor_carbonDioxide >=| 900))) {
    wait until(not (all(#AirQualitySensor).airQualitySensor_carbonDioxide >=| 900))
}
    triggered = false
}
wait until(all(#AirQualitySensor).airQualitySensor_carbonDioxide >=| 900)
all(#Valve).valve_close()
triggered = true

triggered := false
if (triggered == true) {
if (not (not ((#LightSens).lightSensor_brightness < 200))) {
    wait until(not ((#LightSens).lightSensor_brightness < 200))
}
    triggered = false
}
wait until((#LightSens).lightSensor_brightness < 200)
all(#Light).light_moveToBrightness(100, 0)
triggered = true

if (not (all(#PresenceSensor).presenceSensor_presence ==| true)) {
    wait until(all(#PresenceSensor).presenceSensor_presence ==| true)
}
delay(1 MIN)
all(#Camera).camera_captureImage()

if (not (all(#PresenceSensor).presenceSensor_presence ==| true)) {
    wait until(all(#PresenceSensor).presenceSensor_presence ==| true)
}
delay(10 SEC)
all(#Siren).siren_setSirenMode("emergency")

phase := 0
if (phase == 0) {
if (not (all(#ContactSensor).contactSensor_contact ==| false)) {
    wait until(all(#ContactSensor).contactSensor_contact ==| false)
}
    phase = 1
    all(#Speaker).speaker_speak("Welcome")
}
else {
all(#Speaker).speaker_speak("Welcome")
}

phase := 0
if (phase == 0) {
if (not (all(#ContactSensor).contactSensor_contact ==| true)) {
    wait until(all(#ContactSensor).contactSensor_contact ==| true)
}
    phase = 1
    all(#Siren).siren_setSirenMode("police")
}
else {
all(#Siren).siren_setSirenMode("police")
}

phase := 0
if (phase == 0) {
if (not ((#Entrance_ContactSensor).contactSensor_contact == false)) {
    wait until((#Entrance_ContactSensor).contactSensor_contact == false)
}
    phase = 1
    if ((#Main_DoorLock).doorLock_doorLockState != "closed") {
all(#Speaker).speaker_speak("The safe is open")
}
}
else {
if ((#Main_DoorLock).doorLock_doorLockState != "closed") {
all(#Speaker).speaker_speak("The safe is open")
}
}

phase := 0
if (phase == 0) {
if (not (all(#SmokeDetector).smokeDetector_smoke ==| true)) {
    wait until(all(#SmokeDetector).smokeDetector_smoke ==| true)
}
    phase = 1
    all(#Siren).siren_setSirenMode("emergency")
    delay(5 SEC)
all(#Switch).switch_off()
}
else {
all(#Siren).siren_setSirenMode("emergency")
    delay(5 SEC)
all(#Switch).switch_off()
}

phase := 0
if (phase == 0) {
if (not ((#Main_Charger).charger_voltage <= 4000)) {
    wait until((#Main_Charger).charger_voltage <= 4000)
}
    phase = 1
    all(#Speaker).speaker_speak("The charging voltage is low")
}
else {
all(#Speaker).speaker_speak("The charging voltage is low")
}

phase := 0
if (phase == 0) {
if (not ((#Main_Fan).fan_speed == 0)) {
    wait until((#Main_Fan).fan_speed == 0)
}
    phase = 1
    all(#Speaker).speaker_speak("Please check the fan")
}
else {
all(#Speaker).speaker_speak("Please check the fan")
}

phase := 0
if (phase == 0) {
if (not (all(#MotionSensor).motionSensor_motion ==| true)) {
    wait until(all(#MotionSensor).motionSensor_motion ==| true)
}
    phase = 1
    all(#Camera).camera_captureImage()
}
else {
all(#Camera).camera_captureImage()
}

phase := 0
if (phase == 0) {
if (not ((#P_AQ).airQualitySensor_carbonDioxide > 880)) {
    wait until((#P_AQ).airQualitySensor_carbonDioxide > 880)
}
    phase = 1
    (#P_Speaker).speaker_speak("CO2 level danger")
}
else {
(#P_Speaker).speaker_speak("CO2 level danger")
}

phase := 0
if (phase == 0) {
if (not (all(#PresenceSensor).presenceSensor_presence ==| true)) {
    wait until(all(#PresenceSensor).presenceSensor_presence ==| true)
}
    phase = 1
    (#F1_Siren).siren_setSirenMode("emergency")
    delay(3 SEC)
(#F1_Siren).switch_off()
}
else {
(#F1_Siren).siren_setSirenMode("emergency")
    delay(3 SEC)
(#F1_Siren).switch_off()
}

phase := 0
if (phase == 0) {
if (not ((#Lobby_Mot).motionSensor_motion == true)) {
    wait until((#Lobby_Mot).motionSensor_motion == true)
}
    phase = 1
    (#Lobby_Cam).camera_captureImage()
}
else {
(#Lobby_Cam).camera_captureImage()
}

phase := 0
if (phase == 0) {
if (not ((#K_Smoke).smokeDetector_smoke == true)) {
    wait until((#K_Smoke).smokeDetector_smoke == true)
}
    phase = 1
    (#LR_Speaker).speaker_speak("Fire outbreak")
}
else {
(#LR_Speaker).speaker_speak("Fire outbreak")
}

if (not (all(#MotionSensor).motionSensor_motion ==| true or (#Clock).clock_hour >= 23)) {
    wait until(all(#MotionSensor).motionSensor_motion ==| true or (#Clock).clock_hour >= 23)
}
if ((#Clock).clock_hour >= 23) {
all(#DoorLock).doorLock_lock()
}
